/**
 * Assembles the 1200x630 social preview card.
 *
 *   node scripts/compose-social-card.mjs
 *
 * The card is rendered in headless Chrome rather than drawn in a canvas
 * library, because that is the only way to set it in the site's own type: the
 * page below loads the real IBM Plex Sans Condensed and Roboto Mono files that
 * `astro build` downloaded into .astro/fonts/, so the card's title is the same
 * face, weight and letter-spacing as the h1 it previews. Nothing here invents
 * a typeface, and no lettering is generated by the image model.
 *
 * Inputs:
 *   src/assets/images/social/social-specimen.png  (generate-image.mjs)
 *   .astro/fonts/*.woff2                          (astro build)
 * Output:
 *   src/assets/images/social/card.png             (committed, 1200x630)
 *
 * The specimen is trimmed of its near-white surround before placement, so the
 * generated backdrop never shows as a grey panel against the card's white.
 */
import { spawn } from "node:child_process";
import { Buffer } from "node:buffer";
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const WIDTH = 1200;
const HEIGHT = 630;

const SPECIMEN = "src/assets/images/social/social-specimen.png";
const OUT = "src/assets/images/social/card.png";

/* The card's text. Kept identical to the homepage's own hero and readout, so a
   link preview and the page it opens do not disagree. */
const CARD = {
  eyebrow: "SLOP2895 · Semester 1 2027",
  title: "The Sandwich Must Hold",
  lede: "Every lunch is a temporary structure.<br />Study the forces that make it fail.",
  /* Two readout fields, not the homepage's three: "Load case One-handed hold"
     pushes the line past the column and wraps the status marker onto its own
     row. The dropped field is on the page the card links to. */
  readout: ["Specimen 001", "Scale 50 mm"],
  status: "Test in progress",
  institution: "Slop University",
};

/** Finds a font astro downloaded, by the cssVariable name it was asked for. */
async function fontData(prefix) {
  const dir = resolve(ROOT, ".astro/fonts");
  let names;
  try {
    names = await readdir(dir);
  } catch {
    throw new Error(
      ".astro/fonts is missing. Run `pnpm build` first so Astro downloads the " +
        "webfonts this card is set in.",
    );
  }
  const name = names.find((f) => f.startsWith(prefix) && f.endsWith(".woff2"));
  if (!name) {
    throw new Error(
      `no .astro/fonts file starting "${prefix}". Found: ${names.join(", ") || "(none)"}`,
    );
  }
  const buf = await readFile(resolve(dir, name));
  return `data:font/woff2;base64,${buf.toString("base64")}`;
}

/**
 * Trims the generated white backdrop down to the subject, then re-pads it to a
 * square so the compositor's placement does not depend on how tightly the
 * model happened to frame that particular render.
 */
async function trimmedSpecimen() {
  const src = resolve(ROOT, SPECIMEN);
  let png;
  try {
    png = await readFile(src);
  } catch {
    throw new Error(
      `${SPECIMEN} is missing. Run \`node scripts/generate-image.mjs social-specimen\` first.`,
    );
  }
  /* The model's "pure white" backdrop is not white: it renders between RGB 237
     and 251, with a soft gradient. Trimming alone therefore leaves a visibly
     grey panel behind the rig once it sits on the card's true white. So the
     white point is lifted first --- 237 and above clips to 255 --- and only
     then is the backdrop trimmed away. The lift brightens the steel by about
     8/255, which is within the material's own highlight range and reads as
     studio lighting rather than as an edit. */
  /* Two passes, not one chained call: sharp applies its operations in a fixed
     pipeline order in which trim runs BEFORE linear, so `.linear().trim()`
     would trim the original grey backdrop against white and find nothing to
     remove. The lift has to be rendered to a buffer first. */
  const lifted = await sharp(png).linear(1.09, -4).toBuffer();
  const trimmed = await sharp(lifted)
    .trim({ background: "#ffffff", threshold: 6 })
    .toBuffer();
  const { width, height } = await sharp(trimmed).metadata();
  const side = Math.max(width, height);
  const square = await sharp({
    create: {
      width: side,
      height: side,
      channels: 4,
      background: { r: 255, g: 255, b: 255, alpha: 0 },
    },
  })
    .composite([
      {
        input: trimmed,
        left: Math.round((side - width) / 2),
        top: Math.round((side - height) / 2),
      },
    ])
    .png()
    .toBuffer();
  console.log(`specimen: trimmed to ${width}x${height}, padded to ${side}x${side}`);
  return `data:image/png;base64,${square.toString("base64")}`;
}

function html({ display, mono, body, specimen }) {
  return `<!doctype html>
<meta charset="utf-8">
<style>
  @font-face { font-family: "Plex Condensed"; src: url("${display}") format("woff2");
               font-weight: 700; font-display: block; }
  @font-face { font-family: "Roboto Mono"; src: url("${mono}") format("woff2");
               font-weight: 400; font-display: block; }
  @font-face { font-family: "Public Sans"; src: url("${body}") format("woff2");
               font-weight: 100 900; font-display: block; }

  /* The course tokens, copied from src/styles/course.css. Contrast on white:
     charcoal 16.66, tomato 6.35, toast 7.43. */
  :root {
    --paper: #fff; --charcoal: #1f1e1c; --tomato: #b32d1a; --toast: #7a4a1e;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: ${WIDTH}px; height: ${HEIGHT}px; }
  body {
    background: var(--paper); color: var(--charcoal);
    font-family: "Public Sans", sans-serif;
    display: grid; grid-template-columns: 1fr 470px;
    align-items: center; gap: 32px; padding: 52px 60px;
  }
  /* The left column carries its own vertical rhythm and ends with the
     institution, so nothing on this card is positioned absolutely and nothing
     can collide with the readout. */
  .copy { display: flex; flex-direction: column; min-width: 0; }

  .eyebrow {
    font-family: "Roboto Mono", monospace; font-size: 20px; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--toast); margin-bottom: 22px;
  }
  h1 {
    font-family: "Plex Condensed", "Arial Narrow", sans-serif; font-weight: 700;
    font-size: 104px; line-height: 0.93; letter-spacing: 0.005em;
    margin-bottom: 26px;
  }
  .rule { height: 2px; background: var(--charcoal); margin-bottom: 26px; }
  .lede { font-size: 25px; line-height: 1.4; margin-bottom: 34px; }

  /* The readout, set exactly as the homepage's specimen labels: a mono key
     and value per field, with the red status marker last. Red is the site's
     "active load" colour, so it marks the test that is running, not decoration. */
  .readout { display: flex; align-items: center; gap: 16px;
             font-family: "Roboto Mono", monospace; font-size: 16px;
             letter-spacing: 0.06em; text-transform: uppercase;
             white-space: nowrap; }
  .readout span { color: var(--toast); }
  .status { color: var(--tomato); border: 1px solid var(--tomato); padding: 3px 9px; }

  .inst { margin-top: 22px; font-family: "Roboto Mono", monospace; font-size: 15px;
          letter-spacing: 0.12em; text-transform: uppercase; color: var(--toast); }

  figure { justify-self: center; }
  img { display: block; width: 470px; height: 500px; object-fit: contain; }
</style>
<div class="copy">
  <p class="eyebrow">${CARD.eyebrow}</p>
  <h1>${CARD.title}</h1>
  <div class="rule"></div>
  <p class="lede">${CARD.lede}</p>
  <p class="readout">
    ${CARD.readout.map((r) => `<span>${r}</span>`).join("\n    ")}
    <span class="status">${CARD.status}</span>
  </p>
  <p class="inst">${CARD.institution}</p>
</div>
<figure><img src="${specimen}" alt=""></figure>
`;
}

/**
 * Screenshots the card page at exactly 1200x630 and returns the PNG bytes.
 *
 * The page goes to a temp file rather than a data: URL: with the three
 * webfonts and the specimen inlined as base64 it is several megabytes, and
 * passing that as an argv entry fails with E2BIG.
 */
async function shoot(page) {
  const pagePath = resolve(ROOT, ".card.tmp.html");
  await writeFile(pagePath, page);
  const url = `file://${pagePath}`;
  const proc = spawn(CHROME, [
    "--headless=new",
    "--disable-gpu",
    "--hide-scrollbars",
    "--force-device-scale-factor=1",
    `--window-size=${WIDTH},${HEIGHT}`,
    `--screenshot=${resolve(ROOT, ".card.tmp.png")}`,
    "--virtual-time-budget=4000",
    url,
  ]);
  const code = await new Promise((r) => proc.on("exit", r));
  if (code !== 0) throw new Error(`Chrome exited ${code}`);
  return readFile(resolve(ROOT, ".card.tmp.png"));
}

const page = html({
  display: await fontData("font-ibm-plex-sans-condensed-700"),
  mono: await fontData("font-roboto-mono-400"),
  body: await fontData("font-public-sans-100-900-normal"),
  specimen: await trimmedSpecimen(),
});

const shot = await shoot(page);
const { width, height } = await sharp(shot).metadata();
if (width !== WIDTH || height !== HEIGHT) {
  throw new Error(`card rendered ${width}x${height}, expected ${WIDTH}x${HEIGHT}`);
}
await mkdir(dirname(resolve(ROOT, OUT)), { recursive: true });
await writeFile(resolve(ROOT, OUT), shot);
console.log(`wrote ${OUT} (${width}x${height}, ${(shot.length / 1024).toFixed(0)} KB)`);
